function test_parse_markets() {
    $exchange = new \ccxt\async\Exchange(array(
        'id' => 'sampleex',
    ));
    // we don't check empty base or quote inside parseMarkets
    $markets = [array(
    'id' => 'BTC_USD',
    'base' => 'BTC',
    'quote' => 'USD',
), array(
    'id' => null,
    'base' => 'ETH',
    'quote' => 'USD',
), array(
    'id' => 'ETH_USD',
    'base' => null,
    'quote' => 'USD',
), array(
    'id' => 'ETH_USD',
    'base' => 'ETH',
    'quote' => null,
)];
    $parsed_markets = $exchange->parse_markets($markets);
    assert(count($parsed_markets) === 2, 'Expected 3 parsed markets');
    assert($parsed_markets[0] !== null && $parsed_markets[0]['base'] === 'BTC', 'Expected BTC as base for the first market');
}
